#include "frontend.hpp"
#include "frontend_hud.hpp"
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <cmath>
using namespace ofo;
void require(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(int argc,char**argv){try{
 if(argc<2){std::cout<<"real resources argument required\n";return 0;}
 Resources r(argv[1]);auto temp=fs::temp_directory_path()/"openfo_frontend_test";fs::remove_all(temp);
 Frontend requested(r,{},"data/tracks/forest/forest1/geometry/track_geom.w32");require(requested.choice.track=="tracks/forest/forest1/geometry/track_geom.w32","requested geometry normalization");
 Frontend m(r,temp);require(m.page==MenuPage::Start,"start page");require(m.cars.size()==16,"all sixteen car records");require(m.track_slots.size()>30,"authored track grid");require(m.upgrades.size()>20,"upgrade catalog");
 for(const auto&c:m.cars){require(bool(c.icon),"car atlas icon");require(c.stats.weight>0,"authored car mass");require(!c.skins.empty(),"car skins");}
 m.key(13);require(m.page==MenuPage::Profile,"start to profile");m.key(13);require(m.profile_editing,"new profile name entry");for(char c:std::string("TEST PLAYER"))m.profile_character(c);m.key(13);require(m.page==MenuPage::Main&&m.profile_name=="TEST PLAYER","profile creation to main");m.key(13);require(m.page==MenuPage::SinglePlayer,"single player");m.row=1;m.key(13);require(m.page==MenuPage::CarSelect,"quick car dealer");int car=m.selected_car_id();m.key(39);require(car!=m.selected_car_id(),"cycle original car IDs");m.key(13);require(m.page==MenuPage::Transmission,"transmission");m.row=1;m.key(13);require(!m.choice.automatic&&m.page==MenuPage::ClassSelect,"manual transmission");m.key(13);require(m.page==MenuPage::RaceSetup,"track grid");auto group=m.class_tracks();require(!group.empty(),"class slots");for(auto index:group){m.select_track(index);require(!m.selected_stage().empty(),"stage selection");require(r.exists(stage_geometry(m.selected_stage())),"Menu selection resolves actual shared geometry");require(r.exists(m.selected_stage()+"/data/startpoints.bed"),"Menu selection resolves stage spawn");}
 m.row=3;m.key(13);require(m.start||m.message.find("scoring")!=std::string::npos,"race start or unsupported scoring message");m.clear_actions();
 m.open_pause();require(m.pause_context&&!m.showroom().enabled,"pause must not enter showroom");m.row=1;m.key(13);require(m.page==MenuPage::Confirm,"restart confirmation");m.row=1;m.key(13);require(m.restart,"restart action");m.clear_actions();m.open_pause();m.row=2;m.key(13);m.row=0;m.key(13);require(!m.retire&&m.page==MenuPage::Pause,"cancel retire");m.row=3;m.key(13);require(m.page==MenuPage::Options,"pause audio");m.key(9);require(m.page==MenuPage::Controls,"controls tab");m.row=0;m.key(13);m.key('Z');require(m.controls.keys[0]=='Z',"rebind");m.key(9);require(m.page==MenuPage::GameOptions,"game tab");m.row=4;require(m.detail_level==2,"default high detail");m.key(39);require(m.detail_level==3,"detail right cycles ultra");m.key(39);require(m.detail_level==0,"detail cycles low");m.key(37);require(m.detail_level==3,"detail left cycles ultra");m.row=5;float old_bloom=m.bloom_intensity;m.key(13);require(m.bloom_intensity>old_bloom&&m.bloom,"bloom intensity keyboard control");m.row=6;bool old_ao=m.ambient_occlusion;m.key(13);require(m.ambient_occlusion!=old_ao,"AO menu toggle changes actual setting");m.row=7;bool old_ssr=m.water_ssr;m.key(13);require(m.water_ssr!=old_ssr,"water SSR menu toggle changes actual setting");{Frontend saved(r,temp);require(saved.ambient_occlusion==m.ambient_occlusion&&saved.water_ssr==m.water_ssr,"screen effects settings persist per profile");}m.back();require(m.page==MenuPage::Pause,"options returns pause");
 m.open_pause();m.row=5;m.key(13);require(m.photo&&m.page==MenuPage::Pause,"photo action keeps pause context");m.clear_actions();require(!m.photo,"photo action cleared");m.pause_context=false;m.page=MenuPage::Garage;m.money=999999;m.tuning_category=0;auto ids=m.category_upgrades();require(!ids.empty(),"engine upgrades");m.upgrade_index=0;int cash=m.money;m.buy_upgrade();require(m.money<cash,"purchase subtracts cash");require(!m.car_upgrades(m.selected_car_id()).empty(),"purchase owned");Frontend reload(r,temp);require(reload.detail_level==3,"detail persists profile");require(reload.money==m.money&&reload.controls.keys[0]=='Z',"profile and controls persistence");
 auto scene=m.showroom(3);require(scene.enabled&&scene.show_car&&scene.slot==19,"garage camera slot");require(std::isfinite(scene.eye.x)&&scene.fov>0,"camera projection");
 for(MenuPage page:{MenuPage::Start,MenuPage::Profile,MenuPage::CareerAward,MenuPage::Garage,MenuPage::Tuning,MenuPage::Upgrade,MenuPage::Stats,MenuPage::GameOptions,MenuPage::Main,MenuPage::SinglePlayer,MenuPage::RaceSetup,MenuPage::ClassSelect,MenuPage::CarSelect,MenuPage::Transmission,MenuPage::Pause,MenuPage::Confirm,MenuPage::Options,MenuPage::Controls,MenuPage::Credits}){m.page=page;m.row=0;auto cmds=m.draw_commands(1920,1080,.5);require(!cmds.empty(),"screen draw commands");int bands=0;for(const auto&c:cmds){require(std::isfinite(c.x)&&std::isfinite(c.y),"finite draw position");if(c.kind==FrontendDraw::Image&&c.value.find("balks.dds")!=std::string::npos)++bands;}require(bands>=3,"native BED-driven bands");}
 FrontendHud hud(r);RaceOverlayState hs;hs.countdown=2.8;auto countdown=hud.commands(1920,1080,hs);bool native_countdown=false;for(const auto&c:countdown)if(c.kind==FrontendDraw::Image&&c.value.find("race_start_items")!=std::string::npos)native_countdown=true;require(native_countdown,"native countdown atlas");
 hs.countdown=0;hs.elapsed=20;hs.replay=true;hs.replay_paused=true;hs.replay_selected=2;auto replay=hud.commands(1920,1080,hs);int replay_icons=0;for(const auto&c:replay)if(c.kind==FrontendDraw::Image&&c.value.find("replay_napit")!=std::string::npos)++replay_icons;require(replay_icons==5,"all five replay icons");
 hs.replay=false;hs.finished=true;hs.results=true;auto empty_results=hud.commands(1920,1080,hs);for(const auto&c:empty_results)require(c.value.find("RACING")==std::string::npos,"no invented standings");hs.leaderboard.push_back({1,"ACTUAL DRIVER",3,3,102.3,true,true,""});auto results=hud.commands(1920,1080,hs);bool actual=false;for(const auto&c:results)if(c.value=="ACTUAL DRIVER")actual=true;require(actual,"caller supplied standings");
 hs.finished=false;hs.leaderboard.clear();hs.music_title="Test music";hs.music_artist="Artist";hs.music_age=2;auto music=hud.commands(1920,1080,hs);bool music_title=false,music_artist=false,music_panel=false;for(const auto&c:music){music_title|=c.kind==FrontendDraw::Text&&c.value=="Test music";music_artist|=c.kind==FrontendDraw::Text&&c.value=="Artist";music_panel|=c.kind==FrontendDraw::Image&&c.value=="global/overlay/musicbar.dds"&&std::abs(c.w-4*c.h)<.01f;}require(music_title&&music_artist&&music_panel,"native music plaque preserves aspect ratio and actual artist/title");hs.music_age=9;auto expired=hud.commands(1920,1080,hs);for(const auto&c:expired)require(c.value!="Test music"&&c.value!="Artist"&&c.value!="global/overlay/musicbar.dds","music banner expires after eight seconds");
 if(argc>2){Json snapshots=Json::array();for(MenuPage page:{MenuPage::Start,MenuPage::Profile,MenuPage::CareerAward,MenuPage::Garage,MenuPage::Tuning,MenuPage::Upgrade,MenuPage::Stats,MenuPage::GameOptions,MenuPage::Main,MenuPage::SinglePlayer,MenuPage::RaceSetup,MenuPage::ClassSelect,MenuPage::CarSelect,MenuPage::Transmission,MenuPage::Pause,MenuPage::Confirm,MenuPage::Options,MenuPage::Controls,MenuPage::Credits}){m.page=page;m.row=0;Json snapshot={{"title",m.title()},{"page",int(page)},{"commands",Json::array()}};for(const auto&c:m.draw_commands(1280,720,.25))snapshot["commands"].push_back({{"kind",int(c.kind)},{"scale",c.scale},{"heading",c.heading},{"x",c.x},{"y",c.y},{"w",c.w},{"h",c.h},{"u",c.u},{"v",c.v},{"uw",c.uw},{"vh",c.vh},{"color",c.color},{"value",c.value}});snapshots.push_back(snapshot);}std::ofstream(argv[2])<<snapshots.dump();}
 fs::remove_all(temp);std::cout<<"frontend: 16 cars, "<<m.track_slots.size()<<" grid slots, "<<m.upgrades.size()<<" upgrades; navigation, pause, purchase, persistence, cameras and 18 screens passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
